import{_ as t,o,c as a,a5 as n}from"./chunks/framework.7O2hbS7a.js";const u=JSON.parse('{"title":"TORCH Extraction Implementation","description":"","frontmatter":{},"headers":[],"relativePath":"development/torch-implementation.md","filePath":"development/torch-implementation.md"}'),s={name:"development/torch-implementation.md"};function r(d,e,i,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="torch-extraction-implementation" tabindex="-1">TORCH Extraction Implementation <a class="header-anchor" href="#torch-extraction-implementation" aria-label="Permalink to &quot;TORCH Extraction Implementation&quot;">​</a></h1><p>Developer reference for how Aether drives a TORCH data-extraction job end to end: submitting a CRTDL query, polling for completion, and downloading the resulting FHIR NDJSON files.</p><p>This page documents the <em>implementation</em> — the types, functions, and control flow — behind Aether&#39;s use of TORCH&#39;s asynchronous Bulk Data extraction API. For operator-facing usage see the <a href="./../guides/torch-integration.html">TORCH Integration guide</a> and the <a href="./../guides/steps/torch-import.html">TORCH Import step</a>.</p><h2 id="torch-s-two-apis" tabindex="-1">TORCH&#39;s two APIs <a class="header-anchor" href="#torch-s-two-apis" aria-label="Permalink to &quot;TORCH&#39;s two APIs&quot;">​</a></h2><p>TORCH exposes <strong>two</strong> REST APIs, and Aether uses only the first:</p><ul><li><strong><a href="https://medizininformatik-initiative.github.io/torch/api/api.html#fhir-controller" target="_blank" rel="noreferrer">FHIR controller</a></strong> — the extraction API, built on the <a href="http://hl7.org/fhir/R5/async-bulk.html" target="_blank" rel="noreferrer">FHIR Asynchronous Bulk Data Request Pattern</a>: the <code>$extract-data</code> kick-off operation plus the <code>GET /fhir/__status/{jobId}</code> status/manifest endpoint.</li><li><strong><a href="https://medizininformatik-initiative.github.io/torch/api/api.html#task-controller" target="_blank" rel="noreferrer">Task API</a></strong> (task-controller) — controls extraction jobs <em>in execution</em> (inspect, pause, resume, cancel), exposing each job as a FHIR <code>Task</code>. Aether does <strong>not</strong> use it today; job control and <code>Task</code> reads are out of scope (see <a href="https://github.com/medizininformatik-initiative/aether/pull/474" target="_blank" rel="noreferrer">PR #474</a>).</li></ul><h3 id="the-asynchronous-bulk-extraction-flow" tabindex="-1">The asynchronous bulk extraction flow <a class="header-anchor" href="#the-asynchronous-bulk-extraction-flow" aria-label="Permalink to &quot;The asynchronous bulk extraction flow&quot;">​</a></h3><p>Aether drives the FHIR controller through three phases:</p><ol><li><strong>Kick-off</strong> — <code>POST $extract-data</code> creates the extraction job. TORCH returns the job&#39;s status URL (<code>.../fhir/__status/{jobId}</code>) in the <code>Content-Location</code> response header.</li><li><strong>Poll</strong> — Aether polls the status URL. <code>202 Accepted</code> means the job is still running; <code>200 OK</code> means it completed and the response body is the async-bulk <strong>manifest</strong> carrying the output file URLs.</li><li><strong>Download</strong> — Aether downloads each output file.</li></ol><p>The extraction job is identified by a <strong>TORCH job ID</strong> (a UUID, distinct from the Aether pipeline job ID). Aether persists a <strong>job handle</strong> — the job ID plus its status URL — so it can re-attach to an in-flight job after a crash or restart instead of re-submitting (see <em>Handle persistence and resume</em> below). The <code>CONTEXT.md</code> glossary at the repository root defines the domain terms (extraction job, job handle, re-attach, orphan, re-roll).</p><h3 id="extraction-job-status-the-double-status" tabindex="-1">Extraction job status (the &quot;double status&quot;) <a class="header-anchor" href="#extraction-job-status-the-double-status" aria-label="Permalink to &quot;Extraction job status (the &quot;double status&quot;)&quot;">​</a></h3><p>Each extraction job moves through a status lifecycle (coding system <code>https://medizininformatik-initiative.de/torch/job-status</code>):</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>PENDING</code></td><td>Accepted, not yet started</td></tr><tr><td><code>RUNNING_GET_COHORT</code></td><td>Selecting the cohort</td></tr><tr><td><code>RUNNING_PROCESS_BATCH</code></td><td>Extracting patient batches</td></tr><tr><td><code>RUNNING_PROCESS_CORE</code></td><td>Assembling shared (non-patient) <code>core</code> resources</td></tr><tr><td><code>PAUSED</code></td><td>Paused, resumable</td></tr><tr><td><code>TEMP_FAILED</code></td><td>Transient failure — <strong>not terminal</strong>; TORCH retries</td></tr><tr><td><code>COMPLETED</code> / <code>FAILED</code> / <code>CANCELLED</code></td><td>Terminal</td></tr></tbody></table><p>This status appears in <strong>two</strong> places — an artifact of the async-bulk design that carries job state alongside the Task model: the Task API exposes it as a <code>Task</code> business status, and the completion manifest from <code>__status</code> embeds the same job state in a <code>torch-job</code> extension. Aether reads neither representation. It branches purely on the async-bulk <strong>HTTP</strong> status the <code>__status</code> endpoint returns (see the <em>Polling</em> stage below): <code>TEMP_FAILED</code> surfaces as <code>202</code>/<code>503</code>, terminal failure as <code>500</code>, and completion as <code>200</code>.</p><h2 id="source-map" tabindex="-1">Source map <a class="header-anchor" href="#source-map" aria-label="Permalink to &quot;Source map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>internal/pipeline/import.go</code></td><td>Orchestration: submit → persist handle → poll → download, resume, error classification</td></tr><tr><td><code>internal/pipeline/crtdl_prep.go</code></td><td><code>PrepareCRTDL</code> — copies/enriches the CRTDL into the job directory before submission</td></tr><tr><td><code>internal/services/torch_client.go</code></td><td><code>TORCHClient</code>: submit, download, result parsing, file-availability checks, URL resolution, request/response types</td></tr><tr><td><code>internal/services/torch_poller.go</code></td><td><code>PollConfig</code> and <code>handlePollResponse</code>: status interpretation, liveness window, exponential backoff</td></tr><tr><td><code>internal/models/config.go</code></td><td><code>TORCHConfig</code> — the tunable knobs</td></tr><tr><td><code>internal/models/job.go</code></td><td><code>CRTDLPath</code>, <code>TORCHExtractionURL</code>, <code>TORCHJobID</code> — the persisted resume handle</td></tr><tr><td><code>internal/models/step.go</code></td><td><code>StepTorchImport</code> step constant</td></tr></tbody></table><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                          internal/pipeline/import.go</span></span>
<span class="line"><span>┌──────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ importStep.Run  (step == torch)                                      │</span></span>
<span class="line"><span>│   InputTypeTORCHURL ──► executeTORCHDownload  (poll URL directly)    │</span></span>
<span class="line"><span>│   InputTypeCRTDL    ──► executeTORCHExtraction                       │</span></span>
<span class="line"><span>└───────────────────────────────┬──────────────────────────────────────┘</span></span>
<span class="line"><span>                                 ▼</span></span>
<span class="line"><span>        job.TORCHJobID set? ──yes──► re-attach to in-flight job</span></span>
<span class="line"><span>                 │ no</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>   submitAndPersistTORCHHandle</span></span>
<span class="line"><span>     SubmitExtraction ─► POST {base_url}/fhir/$extract-data  (DoOnce, no retry)</span></span>
<span class="line"><span>        └─ 200 + Content-Location header ─► status URL</span></span>
<span class="line"><span>     persist job.TORCHExtractionURL + job.TORCHJobID to state.json</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>   PollExtractionStatus(statusURL)                 internal/services/torch_poller.go</span></span>
<span class="line"><span>     loop:</span></span>
<span class="line"><span>       GET statusURL (DoOnce)</span></span>
<span class="line"><span>       handlePollResponse:</span></span>
<span class="line"><span>         202 / 102 ─► in-progress; log OperationOutcome diagnostics; backoff</span></span>
<span class="line"><span>         200       ─► parseExtractionResult ─► [fileURLs]  ✔ done</span></span>
<span class="line"><span>         404 / 410 ─► ErrHandleDead ─► clear handle, re-submit, re-poll</span></span>
<span class="line"><span>         500       ─► terminal job failure (non-transient)</span></span>
<span class="line"><span>         408/429/other 5xx ─► transient; sleep + backoff; retry</span></span>
<span class="line"><span>       RecordContact() on every 200/202 (resets liveness window)</span></span>
<span class="line"><span>       CheckTimeout(): give up only after extraction_timeout of *silence*</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>   DownloadExtractionFiles([fileURLs], importDir)  internal/services/torch_client.go</span></span>
<span class="line"><span>     per file:</span></span>
<span class="line"><span>       waitForFileAvailability (HEAD, fallback Range GET)</span></span>
<span class="line"><span>       downloadFile ─► stall-guarded stream ─► {job}/import/&lt;name&gt;.ndjson[.zst]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br></div></div><h2 id="stage-reference" tabindex="-1">Stage reference <a class="header-anchor" href="#stage-reference" aria-label="Permalink to &quot;Stage reference&quot;">​</a></h2><h3 id="_1-crtdl-preparation" tabindex="-1">1. CRTDL preparation <a class="header-anchor" href="#_1-crtdl-preparation" aria-label="Permalink to &quot;1. CRTDL preparation&quot;">​</a></h3><p>Before the import step runs, <code>PrepareCRTDL</code> (<code>internal/pipeline/crtdl_prep.go</code>) copies the input CRTDL into the job directory as <code>crtdl.json</code>, or — when CRTDL preprocessing is enabled with at least one enrichment — writes an enriched <code>enriched-crtdl.json</code>. It repoints <code>job.CRTDLPath</code> at that file so every downstream step shares one effective CRTDL. Enrichment adds attributes DIMP needs (for example, <code>Patient.identifier</code>) that the original query may omit.</p><h3 id="_2-submission" tabindex="-1">2. Submission <a class="header-anchor" href="#_2-submission" aria-label="Permalink to &quot;2. Submission&quot;">​</a></h3><p><code>TORCHClient.SubmitExtraction(crtdlPath)</code>:</p><ul><li>Reads the CRTDL, validates it is JSON, and base64-encodes it (<code>encodeCRTDLToBase64</code>).</li><li>Wraps it in a FHIR <code>Parameters</code> resource with a single <code>crtdl</code> parameter carrying <code>valueBase64Binary</code> (<code>TORCHExtractionRequest</code> / <code>TORCHParameter</code>).</li><li><code>POST {base_url}/fhir/$extract-data</code> with <code>Content-Type: application/fhir+json</code> and auth applied via <code>HTTPClient.ApplyAuth</code>.</li><li><strong>Sends with <code>DoOnce</code> — deliberately no retry.</strong> <code>$extract-data</code> is non-idempotent job creation; a retried timeout could spawn a duplicate extraction on the server.</li><li>Reads the <code>Content-Location</code> header (the status URL) and normalizes it to an absolute URL (<code>makeAbsoluteURL</code>). A missing header is a hard error.</li></ul><p><code>SubmitExtractionWithContent(crtdlContent []byte)</code> is the in-memory variant for already-enriched documents; it is otherwise identical (it sends <code>Content-Type: application/json</code>).</p><h3 id="_3-handle-persistence-and-resume" tabindex="-1">3. Handle persistence and resume <a class="header-anchor" href="#_3-handle-persistence-and-resume" aria-label="Permalink to &quot;3. Handle persistence and resume&quot;">​</a></h3><p><code>submitAndPersistTORCHHandle</code> stores the extraction handle <strong>before</strong> the long poll begins:</p><ul><li><code>job.TORCHExtractionURL</code> — the status URL to poll.</li><li><code>job.TORCHJobID</code> — the URL&#39;s trailing path segment (<code>JobIDFromStatusURL</code>), for example <code>.../fhir/__status/{jobId}</code>.</li></ul><p>Both are written to <code>state.json</code> via <code>UpdateJob</code>, so a crash mid-extraction leaves a recoverable handle. On resume, <code>executeTORCHExtraction</code> sees a non-empty <code>job.TORCHJobID</code> and <strong>re-attaches</strong> to the running job instead of submitting a new one.</p><p>If polling later reports the handle is dead (<code>ErrHandleDead</code>, from a <code>404</code>/<code>410</code>), the orchestrator clears both fields, re-submits a fresh extraction, and resumes polling.</p><h3 id="_4-polling" tabindex="-1">4. Polling <a class="header-anchor" href="#_4-polling" aria-label="Permalink to &quot;4. Polling&quot;">​</a></h3><p><code>TORCHClient.PollExtractionStatus(statusURL, showProgress)</code> runs the poll loop; <code>internal/services/torch_poller.go</code> owns the per-response logic and timing state (<code>PollConfig</code>).</p><p>Each iteration issues a single <code>GET</code> (<code>DoOnce</code> — the loop, not the HTTP client, owns retry cadence) with <code>Accept: application/json</code>, then <code>handlePollResponse</code> interprets the status:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th><th>Action</th></tr></thead><tbody><tr><td><code>202 Accepted</code>, <code>102 Processing</code></td><td>Still running</td><td>Read <code>OperationOutcome</code> <code>information</code> diagnostics for progress display; back off and poll again</td></tr><tr><td><code>200 OK</code></td><td>Complete</td><td><code>parseExtractionResult</code> → file URLs → return</td></tr><tr><td><code>404 Not Found</code>, <code>410 Gone</code></td><td>Handle gone</td><td>Return <code>ErrHandleDead</code> (caller re-submits)</td></tr><tr><td><code>500 Internal Server Error</code></td><td>Terminal job failure</td><td>Non-transient error, stop</td></tr><tr><td><code>408</code>, <code>429</code>, other <code>5xx</code></td><td>Transient</td><td>Sleep + backoff, retry</td></tr><tr><td>other <code>4xx</code></td><td>Terminal</td><td>Stop</td></tr></tbody></table><blockquote><p><strong>Note:</strong> <code>500</code> is treated as terminal here even though 5xx is normally retryable, because TORCH surfaces a temporary failure (<code>TEMP_FAILED</code>) as <code>202</code>/<code>503</code> and reserves <code>500</code> for a genuinely failed job.</p></blockquote><p><strong>Liveness window.</strong> <code>extraction_timeout</code> is a <em>no-progress</em> window, not a total cap. <code>CheckTimeout</code> returns true only when <code>time.Since(LastContact) &gt; Timeout</code>, and <code>RecordContact</code> resets <code>LastContact</code> on every <code>200</code>/<code>202</code>. A healthy job that keeps answering — even one running for hours — never trips the timeout; Aether gives up only when TORCH goes silent. See <a href="./../adr/0001-extraction-timeout-liveness.html">ADR 0001</a> for the rationale.</p><p><strong>Exponential backoff.</strong> The poll interval starts at <code>polling_interval</code> and doubles after each in-progress poll (<code>CalculateNextPollInterval</code> / <code>UpdateInterval</code>), capped at <code>max_polling_interval</code>.</p><p>Transient network failures on the GET itself (timeouts, connection resets) are swallowed and retried — the extraction may still be running server-side, and the liveness window is the safety net.</p><h3 id="_5-result-parsing" tabindex="-1">5. Result parsing <a class="header-anchor" href="#_5-result-parsing" aria-label="Permalink to &quot;5. Result parsing&quot;">​</a></h3><p><code>parseExtractionResult</code> accepts two shapes and extracts absolute file URLs:</p><ul><li><strong>FHIR <code>Parameters</code></strong> (<code>TORCHExtractionResult</code>): reads <code>output</code> parameters and their <code>url</code> parts (<code>extractURLsFromFHIRFormat</code>).</li><li><strong>Async-bulk manifest</strong> (<code>TORCHSimpleResponse</code>): <code>{ &quot;requiresAccessToken&quot;: …, &quot;output&quot;: [ { &quot;type&quot;: …, &quot;url&quot;: … } ], &quot;extension&quot;: [ … ] }</code> (<code>extractURLsFromSimpleFormat</code>) — the format the server actually returns today. Aether reads only the <code>output</code> URLs; the manifest&#39;s <code>torch-job</code> / diagnostics extensions are ignored.</li></ul><p>An empty <code>output</code> is not silently accepted: if TORCH reports errors the parser surfaces them; otherwise it returns a &quot;no matching data&quot; message explaining the likely CRTDL causes (criteria matched nothing, out-of-range time period, unknown cohort).</p><p><strong>URL resolution.</strong> <code>makeAbsoluteURL</code> is a pure function that dispatches on the URL shape: absolute URLs pass through, path-relative URLs (<code>/output/x.ndjson</code>) resolve against <code>base_url</code> (<code>resolvePathRelativeURL</code>), and scheme-less host-prefixed URLs (<code>host:8080/…</code>, a known TORCH misconfiguration) inherit <code>base_url</code>&#39;s scheme (<code>prependBaseScheme</code>).</p><h3 id="_6-download" tabindex="-1">6. Download <a class="header-anchor" href="#_6-download" aria-label="Permalink to &quot;6. Download&quot;">​</a></h3><p><code>TORCHClient.DownloadExtractionFiles</code> writes each output file into the job&#39;s <code>import/</code> directory. Per file:</p><ul><li>Derive the filename from the URL&#39;s base, forcing an <code>.ndjson</code> suffix, then add the compression extension via <code>GetCompressedFilename</code>.</li><li><strong><code>waitForFileAvailability</code></strong> polls the file before downloading (TORCH results are often served through a proxy with eventual consistency). It uses a <code>HEAD</code> request, falling back to a <code>Range: bytes=0-0</code> GET when the server answers <code>403</code>, <code>404</code>, or <code>405</code>. It retries up to <code>file_ready_retries</code> times spaced by <code>file_ready_interval</code>; setting <code>file_ready_retries &lt;= 0</code> disables the check.</li><li><strong><code>downloadFile</code> / <code>downloadFileOnce</code></strong> stream the body with <code>Accept: application/fhir+ndjson</code> and optional zstd compression on write.</li></ul><p><strong>Stall watchdog.</strong> Downloads use a dedicated <code>http.Client</code> (<code>downloadClient</code>) with <strong>no whole-request deadline</strong>, so an arbitrarily large but steadily flowing NDJSON completes regardless of total size. Inactivity is bounded instead by a <code>stallGuardReader</code>: each read re-arms a <code>time.AfterFunc</code> timer, and if no bytes arrive within <code>download_stall_timeout</code> the timer cancels the request context. The cancellation is reported as <code>errDownloadStalled</code> rather than a generic &quot;context canceled&quot;. The watchdog is armed before even an error body is read, so a proxy that flushes <code>4xx</code>/<code>5xx</code> headers then goes silent is bounded too.</p><p><strong>Retry.</strong> <code>downloadFile</code> retries only a retryable <code>*TORCHError</code> (a transient one), using the shared client&#39;s backoff config. A stall or a mid-body write error is <em>not</em> a <code>*TORCHError</code> and is not retried — restarting from scratch would only repeat the stall or waste a full re-transfer.</p><p>Each downloaded file yields a <code>models.FHIRDataFile</code> with size, resource (<code>LineCount</code>) count, and <code>SourceStep: StepTorchImport</code>.</p><h3 id="_7-error-classification" tabindex="-1">7. Error classification <a class="header-anchor" href="#_7-error-classification" aria-label="Permalink to &quot;7. Error classification&quot;">​</a></h3><p><code>classifyImportError</code> decides whether a failure is transient (pipeline may retry / pause and resume) or terminal:</p><ul><li>It unwraps a <code>*services.TORCHError</code> (via <code>errors.As</code>, so wrapped submit/poll/download errors are caught) and returns its <code>ErrorType</code>.</li><li>For <code>torch</code>/<code>http</code> import steps, a bare network error is transient.</li><li>Everything else defaults to non-transient.</li></ul><p><code>TORCHError</code> carries <code>Operation</code> (<code>submit</code>/<code>poll</code>/<code>download</code>), <code>StatusCode</code>, <code>Message</code>, and <code>ErrorType</code>; <code>IsRetryable()</code> is true only for <code>models.ErrorTypeTransient</code>.</p><h3 id="direct-torch-result-url" tabindex="-1">Direct TORCH result URL <a class="header-anchor" href="#direct-torch-result-url" aria-label="Permalink to &quot;Direct TORCH result URL&quot;">​</a></h3><p>When the input is an already-complete TORCH result URL (<code>InputType == InputTypeTORCHURL</code>), <code>executeTORCHDownload</code> skips submission entirely: it polls the URL directly (expecting an immediate <code>200</code>) and downloads the listed files.</p><h2 id="data-types" tabindex="-1">Data types <a class="header-anchor" href="#data-types" aria-label="Permalink to &quot;Data types&quot;">​</a></h2><p>Defined in <code>internal/services/torch_client.go</code>:</p><table tabindex="0"><thead><tr><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>TORCHExtractionRequest</code> / <code>TORCHParameter</code></td><td>Kickoff body: FHIR <code>Parameters</code> with a base64 <code>crtdl</code> parameter</td></tr><tr><td><code>TORCHExtractionResult</code> / <code>TORCHResultParameter</code> / <code>TORCHResultPart</code></td><td>FHIR <code>Parameters</code> result format</td></tr><tr><td><code>TORCHSimpleResponse</code> / <code>TORCHSimpleOutput</code></td><td>Simplified <code>{ output: [ { type, url } ] }</code> result format</td></tr><tr><td><code>OperationOutcome</code> / <code>OperationOutcomeIssue</code></td><td>Progress diagnostics parsed from <code>202</code> bodies</td></tr><tr><td><code>TORCHError</code></td><td>Structured submit/poll/download error with retryability</td></tr></tbody></table><p>Sentinel errors: <code>ErrExtractionTimeout</code>, <code>ErrHandleDead</code>, <code>ErrInvalidCRTDL</code>.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p><code>TORCHConfig</code> (<code>internal/models/config.go</code>) tunes the flow. Defaults are set in <code>DefaultConfig</code> and range-checked in <code>TORCHConfig.Validate</code>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Effect</th></tr></thead><tbody><tr><td><code>base_url</code></td><td>—</td><td>TORCH server base URL (required when the torch step is enabled)</td></tr><tr><td><code>auth</code></td><td>—</td><td><code>models.AuthConfig</code>, the same block as <code>dimp</code> and <code>send</code>. <code>TORCHConfig.EffectiveAuth</code> reads it.</td></tr><tr><td><code>extraction_timeout</code></td><td><code>30m</code></td><td>Liveness window — max time to wait <strong>without</strong> a response; reset on every <code>200</code>/<code>202</code></td></tr><tr><td><code>polling_interval</code></td><td><code>5s</code></td><td>Initial status poll interval (must be ≥ <code>1s</code>)</td></tr><tr><td><code>max_polling_interval</code></td><td><code>30s</code></td><td>Backoff cap (must be ≥ <code>polling_interval</code>)</td></tr><tr><td><code>file_ready_retries</code></td><td><code>10</code></td><td>Availability checks before download; <code>0</code> disables the check</td></tr><tr><td><code>file_ready_interval</code></td><td><code>10s</code></td><td>Delay between availability checks</td></tr><tr><td><code>download_stall_timeout</code></td><td><code>60s</code></td><td>Inactivity window while streaming a file; <code>0</code> uses the built-in default</td></tr></tbody></table><p><code>TORCHConfig</code> also keeps the deprecated flat auth fields (<code>Username</code>, <code>Password</code>, <code>OAuthIssuerURI</code>, <code>OAuthClientID</code>, <code>OAuthClientSecret</code>) for older configuration files. <code>EffectiveAuth</code> maps them to an <code>AuthConfig</code>, thus the client reads one shape only. <code>Validate</code> refuses a config that sets both shapes, and <code>LoadConfig</code> writes a deprecation warning for the flat fields.</p><p>See the <a href="./../api-reference/config-reference.html#torch">Configuration Reference</a> for the operator-facing table.</p><h2 id="persisted-job-handle" tabindex="-1">Persisted job handle <a class="header-anchor" href="#persisted-job-handle" aria-label="Permalink to &quot;Persisted job handle&quot;">​</a></h2><p>For resume, the following <code>PipelineJob</code> fields (<code>internal/models/job.go</code>) are written to <code>state.json</code>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Purpose</th></tr></thead><tbody><tr><td><code>CRTDLPath</code></td><td>The effective CRTDL used for submission (decoupled from the raw input source)</td></tr><tr><td><code>TORCHExtractionURL</code></td><td>The <code>Content-Location</code> status URL to re-poll</td></tr><tr><td><code>TORCHJobID</code></td><td>The extraction job ID (handle) used to re-attach to an in-flight job</td></tr></tbody></table><h2 id="testing-seams" tabindex="-1">Testing seams <a class="header-anchor" href="#testing-seams" aria-label="Permalink to &quot;Testing seams&quot;">​</a></h2><p>The import step depends on the <code>Extractor</code> interface — <code>SubmitExtraction</code>, <code>PollExtractionStatus</code>, <code>DownloadExtractionFiles</code> — which <code>TORCHClient</code> satisfies. <code>extractorFactory</code> (<code>internal/pipeline/import.go</code>) builds it, and <code>SetExtractorFactoryForTesting</code> / <code>ResetExtractorFactory</code> swap in a fake so tests exercise submit/poll/download without a live TORCH server. Pure helpers such as <code>makeAbsoluteURL</code>, <code>CalculateNextPollInterval</code>, and the <code>PollConfig</code> liveness methods are unit-tested directly.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./architecture.html">Architecture</a> — system-wide design and data flow</li><li><a href="./../guides/torch-integration.html">TORCH Integration</a> — operator-facing guide</li><li><a href="./../adr/0001-extraction-timeout-liveness.html">ADR 0001: Extraction timeout liveness</a></li><li><a href="./../api-reference/config-reference.html#torch">Configuration Reference</a> — TORCH config knobs</li></ul>`,71)])])}const b=t(s,[["render",r]]);export{u as __pageData,b as default};
